from __future__ import annotations

import base64
import shutil
import subprocess
import sys
import traceback
from datetime import datetime
from pathlib import Path

PROJECT = Path(r"C:\PhoCap")
APP = PROJECT / "app"

MAIN = APP / "main.py"
MENU = APP / "templates" / "partials" / "dropdown_menu_v1.html"
ROUTER = APP / "routers" / "data_tools.py"
TEMPLATE = APP / "templates" / "data_tools" / "survey_cleanup.html"

EXPORTS = PROJECT / "exports"
STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = EXPORTS / f"backup_source_bai_13b_10_v3_18b_{STAMP}"

ROUTER_CODE = base64.b64decode(
    ""
).decode("utf-8")

TEMPLATE_CODE = base64.b64decode(
    ""
).decode("utf-8")


def read_text(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy: {path}")
    return path.read_text(encoding="utf-8-sig")


def backup_source() -> None:
    for src in (ROUTER, TEMPLATE):
        if src.exists():
            dst = BACKUP / src.relative_to(PROJECT)
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)


def restore_source() -> None:
    for target in (ROUTER, TEMPLATE):
        src = BACKUP / target.relative_to(PROJECT)
        if src.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, target)


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


def verify_existing_install() -> None:
    main_text = read_text(MAIN)
    menu_text = read_text(MENU)

    required_main = [
        "data_tools_router",
        "app.include_router(data_tools_router)",
    ]
    for item in required_main:
        if item not in main_text:
            raise RuntimeError(
                "V3.18A chưa được cài đầy đủ: "
                f"main.py thiếu {item}"
            )

    required_menu = [
        "1.3. Công cụ dữ liệu",
        "1.3.1. Dọn dẹp dữ liệu điều tra",
        "/cong-cu-du-lieu/don-du-lieu-dieu-tra",
    ]
    for item in required_menu:
        if item not in menu_text:
            raise RuntimeError(
                "V3.18A chưa được cài đầy đủ: "
                f"menu thiếu {item}"
            )


def verify_new_files() -> None:
    subprocess.run(
        [sys.executable, "-m", "py_compile", str(ROUTER)],
        cwd=PROJECT,
        check=True,
    )

    from jinja2 import Environment, FileSystemLoader

    env = Environment(
        loader=FileSystemLoader(str(APP / "templates"))
    )
    env.get_template("data_tools/survey_cleanup.html")

    router_text = read_text(ROUTER)
    tpl_text = read_text(TEMPLATE)

    for item in (
        "EXPECTED_BATCH_COUNT = 130",
        'CONFIRM_PHRASE = "XOA DU LIEU THU 2026-2027"',
        "def _build_delete_plan",
        "def _backup_database",
        "def _execute_cleanup",
        "PRAGMA foreign_key_check",
        "BEGIN IMMEDIATE",
        "survey_batches",
    ):
        if item not in router_text:
            raise RuntimeError(
                f"Router V3.18B thiếu: {item}"
            )

    for item in (
        "DỌN TOÀN BỘ DỮ LIỆU THỬ",
        "XOA DU LIEU THU 2026-2027",
        "Đợt được giữ nguyên",
        "Hộ dùng chung phải giữ",
    ):
        if item not in tpl_text:
            raise RuntimeError(
                f"Template V3.18B thiếu: {item}"
            )


def main() -> int:
    print("=" * 104)
    print(
        "BÀI 13B-10 V3.18B - "
        "DỌN TOÀN BỘ DỮ LIỆU THỬ NĂM 2026-2027"
    )
    print("=" * 104)
    print()
    print("PHẠM VI ĐÃ CHỐT:")
    print(" - GIỮ 130 bản ghi survey_batches 2026-2027.")
    print(" - GIỮ 130 xã/phường, danh mục trường, tài khoản.")
    print(" - GIỮ đội ngũ, học sinh, danh mục, năm học.")
    print(" - XÓA dữ liệu nghiệp vụ thử của 2026-2027.")
    print(" - Hộ còn dùng ở đợt/năm khác sẽ được GIỮ.")
    print()
    print("AN TOÀN:")
    print(" - Cài V3.18B KHÔNG xóa dữ liệu.")
    print(" - Chỉ khi ADMIN/SỞ vào màn hình, đánh dấu xác nhận,")
    print("   nhập đúng câu xác nhận và bấm nút đỏ thì mới xóa.")
    print(" - Trước DELETE tự backup phocap.db.")
    print(" - DELETE chạy trong transaction + foreign_key_check.")
    print(" - Lỗi giữa chừng => rollback.")
    print()

    verify_existing_install()

    EXPORTS.mkdir(parents=True, exist_ok=True)
    BACKUP.mkdir(parents=True, exist_ok=False)
    backup_source()

    print("Backup source V3.18A:", BACKUP)

    try:
        ROUTER.write_text(
            ROUTER_CODE,
            encoding="utf-8",
        )
        TEMPLATE.write_text(
            TEMPLATE_CODE,
            encoding="utf-8",
        )

        verify_new_files()
        clear_cache()

        print()
        print("CÀI ĐẶT BÀI 13B-10 V3.18B THÀNH CÔNG")
        print()
        print("LƯU Ý: CÀI XONG VẪN CHƯA XÓA DỮ LIỆU.")
        print("Hãy mở màn hình Công cụ dữ liệu để xem")
        print("tổng phạm vi trước khi bấm nút đỏ.")
        return 0

    except Exception:
        traceback.print_exc()
        print()
        print("CÓ LỖI - ĐANG KHÔI PHỤC V3.18A...")
        restore_source()
        clear_cache()
        print("ĐÃ KHÔI PHỤC SOURCE V3.18A.")
        print("Backup:", BACKUP)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
